/**
 * @name MXPage.js
 * @version 0.0.2
 * @create 2015-09-15
 * @lastmodified 2015-09-15 17:36
 * @description jQuery page navigation plugin
 * @author MuFeng (http://mufeng.me)
 * @url http://mufeng.me
 **/
;(function ($) {
    var array, MXPage = function (x, y) {
        this.settings = x;
        this.element = $(y);

        this.layout();
    };

    MXPage.prototype = {
        layout: function () {
            if (this.settings.maxPage <= 1) return;

            this.fireEvent();

            //最前页
            this.build(1, 'mxpage-front', this.settings.frontPageText);

            //上一页
            this.build(Math.max(1, this.settings.currentPage - 1), 'mxpage-previous', this.settings.previousText);

            //中间
            this.element.children('.pagination-links').append('<span class="paging-input"> '+this.settings.currentPage+'/'+this.settings.maxPage+' </span></span>');

            //下一页
            this.build(Math.min(this.settings.maxPage, this.settings.currentPage + 1), 'mxpage-next', this.settings.nextText);

            //最后页
            this.build(this.settings.maxPage, 'mxpage-last', this.settings.lastPageText);

            //绑定点击事件
            this.addEvent();
        },

        build: function (index, className, title) {
            title = title || index;

            var html,
                that = this;

            if (className == 'mxpage-default' && this.settings.currentPage == index) {
                html = $('<span class="tablenav-pages-navspan">' + index + '</span>')
            }else{
                html = $('<a href="javascript:;" class="mxpage pagination-links ' + className + '" data-page="' + index + '">' + title + '</a>')
            }

            that.element.children('.pagination-links').append(html);
        },

        addEvent: function () {
            var that = this;

            that.element.on('click', '.mxpage', function (event) {
                var $this = $(this),
                    index = parseInt($this.attr('data-page'));

                if (that.settings.currentPage == index) return;

                that.settings.currentPage = index;
                that.layout();

                //回调
                that.settings.click(index, $this);
            });
        },

        fireEvent: function () {
            if (this.element.children('.pagination-links')) {
                this.element.children('.pagination-links').remove();
                this.element.off('click');
            }

            this.element.append('<span class="pagination-links"></span>');
        }
    };

    $.mxpage = function (x, y) {
        //参数合并
        x = $.extend({
            perPage: 10,
            currentPage: 1,
            maxPage: 1,
            previousText: 'previous',
            nextText: 'next',
            frontPageText: 'front page',
            lastPageText: 'last page',
            click: function (index, $element) {}
        }, x);

        $.data(y, 'mxpage', new MXPage(x, y));

        return y;
    };

    $.fn.mxpage = function (x) {
        return $.mxpage(x, this);
    };
})(jQuery);

function cloneObject(src) {
    if (src == null || typeof src != "object") {
        return src
    }
    if (src instanceof Date) {
        var clone = new Date(src.getDate());
        return clone
    }
    if (src instanceof Array) {
        var clone = [];
        for (var i = 0, len = src.length; i < len; i++) {
            clone[i] = src[i]
        }
        return clone
    }
    if (src instanceof Object) {
        var clone = {};
        for (var key in src) {
            if (src.hasOwnProperty(key)) {
                clone[key] = cloneObject(src[key])
            }
        }
        return clone
    }
}

function hermitInit() {
    var aps = document.getElementsByClassName("aplayer");
    var apnum = 0;
    ap = [];
    if (HermitX.sat == "1"){
        var setTheme = [];
    }
    var xhr = [];
    var option = [];
    for (var i = 0; i < aps.length; i++) {
        if (aps[i].dataset.songs) {
            option[i] = cloneObject(aps[i].dataset);
            option[i].element = aps[i];
            xhr[i] = new XMLHttpRequest();
            xhr[i].onreadystatechange = function() {
                var index = xhr.indexOf(this);
                var op = option[index];
                op.storageName = "HxAP-Setting";
                if (this.readyState === 4) {
                    if (this.status >= 200 && this.status < 300 || this.status === 304) {
                        var response = JSON.parse(this.responseText);
                        op.music = response.msg.songs;
                        if (op.music === undefined) {
                            console.warn("Hermit-X failed to load " + option[index].songs);
                            return false;
                        }
                        if (op.music.length === 1) {
                            op.music = op.music[0];
                        }
                        if (op.autoplay) {
                            op.autoplay = (op.autoplay === "true");
                        }
                        if (op.listfolded) {
                            op.listFolded = (op.listfolded === "true");
                        }
                        if (op.mutex) {
                            op.mutex = (op.mutex === "true");
                        }
                        if (op.narrow) {
                            op.narrow = (op.narrow === "true");
                        }
                        ap[i] = new APlayer(op);
                        ap[i].parseRespons = response;
                        if (window.APlayerCall && window.APlayerCall[i]) window.APlayerCall[i]();
                        if (window.APlayerloadAllCall && aps.length != ap.length) {
                            window.APlayerloadAllCall();
                        }
                        if (HermitX.sat == "1") {
                            setTheme[i] = (index) => {
                                if (!ap[i].list.audios[index].theme) {
                                    const colorThief = new ColorThief();
                                    colorThief.getColorAsync(ap[i].list.audios[index].cover, function (color) {
                                        ap[i].theme(`rgb(${color[0]}, ${color[1]}, ${color[2]})`, index);
                                    });
                                }
                            };
                            setTheme[i](ap[i].list.index);
                            ap[i].on('listswitch', (data) => {
                                setTheme[i](data.index);
                            });
                        }
                    } else {
                        console.error("Request was unsuccessful: " + this.status);
                    }
                }
            };
            var scope = option[i].songs.split("#:");
            apiurl = HermitX.ajaxurl + "?action=hermit&scope=" + option[i].songs.split("#:")[0] + "&id=" + option[i].songs.split("#:")[1] + "&_nonce=" + option[i]._nonce;
            xhr[i].open("get", apiurl, true);
            xhr[i].send(null);
        }
    }
}

function reloadHermit() {
    for (var i = 0; i < ap.length; i++) {
        try {
            ap[i].destroy()
        } catch (e) {}
    }
    hermitInit()
}
